const KNOWN_OPTION_KEYS = new Set([
    "generate_memories",
    "use_memories",
    "dedicated_tools",
    "disable_on_external_context",
    "version",
    "dual_write",
    "extract_model",
    "consolidation_model",
    "max_raw_memories_for_consolidation",
